/** A single open document tab. */
export interface EditorTab {
  id: string;
  /** Display name shown in the tab bar. */
  filename: string;
  /** Current editor buffer. */
  content: string;
  /** Last saved buffer — used to detect unsaved changes. */
  savedContent: string;
  /**
   * FileSystem Access API handle when available.
   * Undefined for new unsaved files or fallback-opened files.
   */
  fileHandle?: FileSystemFileHandle;
}

export type CloseChoice = 'save' | 'discard' | 'cancel';

export interface OpenFileResult {
  filename: string;
  content: string;
  fileHandle?: FileSystemFileHandle;
}

/** Canonical extension ↔ MIME mapping for pickers and fallbacks. */
export interface FileTypeEntry {
  ext: string;
  mime: string;
  label: string;
}

export const FILE_TYPES: readonly FileTypeEntry[] = [
  { ext: '.txt', mime: 'text/plain', label: 'Text' },
  { ext: '.text', mime: 'text/plain', label: 'Text' },
  { ext: '.java', mime: 'text/x-java-source', label: 'Java' },
  { ext: '.py', mime: 'text/x-python', label: 'Python' },
  { ext: '.bat', mime: 'application/x-bat', label: 'Batch' },
  { ext: '.cmd', mime: 'application/x-bat', label: 'Batch' },
  { ext: '.sh', mime: 'text/x-shellscript', label: 'Shell' },
  { ext: '.bash', mime: 'text/x-shellscript', label: 'Shell' },
  { ext: '.c', mime: 'text/x-c', label: 'C' },
  { ext: '.h', mime: 'text/x-c', label: 'C header' },
  { ext: '.cpp', mime: 'text/x-c++', label: 'C++' },
  { ext: '.hpp', mime: 'text/x-c++', label: 'C++ header' },
  { ext: '.json', mime: 'application/json', label: 'JSON' },
  { ext: '.html', mime: 'text/html', label: 'HTML' },
  { ext: '.js', mime: 'text/javascript', label: 'JavaScript' },
  { ext: '.css', mime: 'text/css', label: 'CSS' },
] as const;

/** Flat list of accepted extensions (for `<input accept>` fallback). */
export const ACCEPTED_EXTENSIONS = FILE_TYPES.map((t) => t.ext);

export const DEFAULT_FILENAME = 'untitled.txt';

const EXTENSION_LOOKUP = new Map(FILE_TYPES.map((t) => [t.ext, t]));

/** Extract a known extension from a filename (e.g. "script.py" → ".py"). */
export function parseAcceptedExtension(filename: string): FileTypeEntry | null {
  const base = filename.split(/[/\\]/).pop() ?? filename;
  const dot = base.lastIndexOf('.');
  if (dot <= 0 || dot === base.length - 1) return null;
  return EXTENSION_LOOKUP.get(base.slice(dot).toLowerCase()) ?? null;
}

/** Default file type when no extension is present. */
export function defaultFileType(): FileTypeEntry {
  return EXTENSION_LOOKUP.get('.txt')!;
}
