import type { EditorTab } from './types';

export interface TabBarCallbacks {
  onSelect: (id: string) => void;
  onClose: (id: string) => void;
}

/**
 * Renders and manages the tab bar UI.
 * Each tab shows filename, unsaved dot, and close button.
 */
export class TabBar {
  private readonly container: HTMLElement;
  private readonly scrollArea: HTMLElement;
  private tabs: EditorTab[] = [];
  private activeId: string | null = null;
  private callbacks: TabBarCallbacks;

  constructor(parent: HTMLElement, callbacks: TabBarCallbacks) {
    this.callbacks = callbacks;
    this.container = document.createElement('div');
    this.container.className =
      'flex min-w-0 flex-1 items-stretch bg-slate-900/80 sm:border-b-0';

    this.scrollArea = document.createElement('div');
    this.scrollArea.className =
      'flex min-h-touch flex-1 items-stretch overflow-x-auto overscroll-x-contain';
    this.scrollArea.setAttribute('role', 'tablist');
    this.scrollArea.setAttribute('aria-label', 'Open files');

    this.container.appendChild(this.scrollArea);
    parent.appendChild(this.container);
  }

  setTabs(tabs: EditorTab[], activeId: string | null): void {
    this.tabs = tabs;
    this.activeId = activeId;
    this.container.classList.toggle('hidden', tabs.length === 0);
    this.render();
  }

  private render(): void {
    this.scrollArea.replaceChildren();

    for (const tab of this.tabs) {
      const isActive = tab.id === this.activeId;
      const isDirty = tab.content !== tab.savedContent;

      const tabEl = document.createElement('div');
      tabEl.className = [
        'group flex min-h-touch shrink-0 items-center gap-1 border-r border-slate-800 px-2',
        isActive
          ? 'bg-slate-950 text-slate-100'
          : 'bg-slate-900 text-slate-400 hover:bg-slate-800/80 hover:text-slate-200',
      ].join(' ');
      tabEl.setAttribute('role', 'tab');
      tabEl.setAttribute('aria-selected', String(isActive));
      tabEl.dataset.tabId = tab.id;

      const selectBtn = document.createElement('button');
      selectBtn.type = 'button';
      selectBtn.className =
        'flex min-h-touch min-w-0 items-center gap-2 px-2 text-sm font-medium';
      selectBtn.title = tab.filename;

      if (isDirty) {
        const dot = document.createElement('span');
        dot.className = 'h-2 w-2 shrink-0 rounded-full bg-amber-400';
        dot.setAttribute('aria-label', 'Unsaved changes');
        selectBtn.appendChild(dot);
      }

      const label = document.createElement('span');
      label.className = 'max-w-[8rem] truncate sm:max-w-[12rem]';
      label.textContent = tab.filename;
      selectBtn.appendChild(label);

      selectBtn.addEventListener('click', () => this.callbacks.onSelect(tab.id));

      const closeBtn = document.createElement('button');
      closeBtn.type = 'button';
      closeBtn.className =
        'flex min-h-touch min-w-touch shrink-0 items-center justify-center rounded-md text-slate-500 hover:bg-slate-700 hover:text-slate-200';
      closeBtn.setAttribute('aria-label', `Close ${tab.filename}`);
      closeBtn.innerHTML = `
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
          <path d="M4 4l8 8M12 4l-8 8" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
        </svg>
      `;
      closeBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        this.callbacks.onClose(tab.id);
      });

      tabEl.append(selectBtn, closeBtn);
      this.scrollArea.appendChild(tabEl);
    }
  }
}
