import type { CloseChoice } from './types';

/**
 * Modal dialog for unsaved-changes confirmation.
 * Returns the user's choice: save, discard, or cancel.
 */
export function showUnsavedDialog(filename: string): Promise<CloseChoice> {
  return new Promise((resolve) => {
    const overlay = document.createElement('div');
    overlay.className =
      'fixed inset-0 z-50 flex items-end justify-center bg-black/60 p-4 sm:items-center';
    overlay.setAttribute('role', 'dialog');
    overlay.setAttribute('aria-modal', 'true');
    overlay.setAttribute('aria-labelledby', 'unsaved-title');

    overlay.innerHTML = `
      <div class="w-full max-w-md rounded-2xl border border-slate-700 bg-slate-900 p-6 shadow-2xl">
        <h2 id="unsaved-title" class="text-lg font-semibold text-slate-100">Unsaved changes</h2>
        <p class="mt-2 text-sm text-slate-400">
          <span class="font-medium text-slate-200">${escapeHtml(filename)}</span>
          has unsaved changes. Save before closing?
        </p>
        <div class="mt-6 flex flex-col gap-2 sm:flex-row sm:justify-end">
          <button type="button" data-action="cancel"
            class="min-h-touch min-w-touch rounded-lg px-4 py-3 text-sm font-medium text-slate-300 hover:bg-slate-800">
            Cancel
          </button>
          <button type="button" data-action="discard"
            class="min-h-touch min-w-touch rounded-lg px-4 py-3 text-sm font-medium text-red-400 hover:bg-red-950/40">
            Discard
          </button>
          <button type="button" data-action="save"
            class="min-h-touch min-w-touch rounded-lg bg-sky-600 px-4 py-3 text-sm font-medium text-white hover:bg-sky-500">
            Save
          </button>
        </div>
      </div>
    `;

    const cleanup = (choice: CloseChoice) => {
      overlay.remove();
      document.removeEventListener('keydown', onKeyDown);
      resolve(choice);
    };

    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') cleanup('cancel');
    };

    overlay.addEventListener('click', (e) => {
      const target = e.target as HTMLElement;
      const action = target.closest('[data-action]')?.getAttribute('data-action');
      if (action === 'save' || action === 'discard' || action === 'cancel') {
        cleanup(action);
      }
      if (target === overlay) cleanup('cancel');
    });

    document.addEventListener('keydown', onKeyDown);
    document.body.appendChild(overlay);
    overlay.querySelector<HTMLButtonElement>('[data-action="save"]')?.focus();
  });
}

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/** Simple toast for status messages. */
export function showToast(message: string, durationMs = 2500): void {
  const toast = document.createElement('div');
  toast.className =
    'fixed bottom-4 left-1/2 z-50 -translate-x-1/2 rounded-lg bg-slate-800 px-4 py-3 text-sm text-slate-100 shadow-lg border border-slate-700';
  toast.textContent = message;
  toast.setAttribute('role', 'status');
  document.body.appendChild(toast);

  window.setTimeout(() => toast.remove(), durationMs);
}
