import type { OpenFileResult } from './types';
import {
  DEFAULT_FILENAME,
  FILE_TYPES,
  defaultFileType,
  parseAcceptedExtension,
} from './types';

/** Whether the File System Access API is available. */
export function supportsFileSystemAccess(): boolean {
  return 'showOpenFilePicker' in window && 'showSaveFilePicker' in window;
}

/** Build the full accept map for open dialogs (all supported types). */
function buildAcceptMap(): Record<string, string[]> {
  const map: Record<string, string[]> = {};
  for (const { ext, mime } of FILE_TYPES) {
    if (!map[mime]) map[mime] = [];
    if (!map[mime].includes(ext)) map[mime].push(ext);
  }
  return map;
}

/**
 * Build save-picker types with the filename's extension first.
 *
 * Chromium picks a default type from `types` and may append that extension to
 * suggestedName — putting every MIME in one entry causes wrong suffixes like
 * "script.py.json". Matching the open extension first avoids that.
 */
function buildSavePickerTypes(suggestedName: string): FilePickerAcceptType[] {
  const allAccept = buildAcceptMap();
  const matched = parseAcceptedExtension(suggestedName);

  if (matched) {
    return [
      {
        description: `${matched.label} files`,
        accept: { [matched.mime]: [matched.ext] },
      },
      {
        description: 'All supported text files',
        accept: allAccept,
      },
    ];
  }

  const fallback = defaultFileType();
  return [
    {
      description: `${fallback.label} files`,
      accept: { [fallback.mime]: ['.txt', '.text'] },
    },
    {
      description: 'All supported text files',
      accept: allAccept,
    },
  ];
}

/** Read text from a File object. */
function readFileAsText(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result ?? ''));
    reader.onerror = () => reject(reader.error);
    reader.readAsText(file);
  });
}

/** Open a file via FS API or hidden input fallback. */
export async function openFile(): Promise<OpenFileResult | null> {
  if (supportsFileSystemAccess()) {
    try {
      const [handle] = await window.showOpenFilePicker!({
        multiple: false,
        types: [{ description: 'Text files', accept: buildAcceptMap() }],
      });
      const file = await handle.getFile();
      const content = await readFileAsText(file);
      return { filename: file.name, content, fileHandle: handle };
    } catch (err) {
      if ((err as DOMException).name === 'AbortError') return null;
      throw err;
    }
  }

  return new Promise((resolve) => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = FILE_TYPES.map((t) => t.ext).join(',');
    input.style.display = 'none';
    document.body.appendChild(input);

    input.addEventListener('change', async () => {
      const file = input.files?.[0];
      document.body.removeChild(input);
      if (!file) {
        resolve(null);
        return;
      }
      const content = await readFileAsText(file);
      resolve({ filename: file.name, content });
    });

    input.addEventListener('cancel', () => {
      document.body.removeChild(input);
      resolve(null);
    });

    input.click();
  });
}

/** Save content to an existing handle, or prompt Save As. */
export async function saveFile(
  content: string,
  filename: string,
  existingHandle?: FileSystemFileHandle
): Promise<{ filename: string; fileHandle?: FileSystemFileHandle } | null> {
  if (existingHandle) {
    const writable = await existingHandle.createWritable();
    await writable.write(content);
    await writable.close();
    return { filename: existingHandle.name, fileHandle: existingHandle };
  }

  return saveFileAs(content, filename);
}

/** Save As — always prompts for destination. */
export async function saveFileAs(
  content: string,
  suggestedName: string
): Promise<{ filename: string; fileHandle?: FileSystemFileHandle } | null> {
  const name = suggestedName || DEFAULT_FILENAME;

  if (supportsFileSystemAccess()) {
    try {
      const handle = await window.showSaveFilePicker!({
        suggestedName: name,
        types: buildSavePickerTypes(name),
      });
      const writable = await handle.createWritable();
      await writable.write(content);
      await writable.close();
      return { filename: handle.name, fileHandle: handle };
    } catch (err) {
      if ((err as DOMException).name === 'AbortError') return null;
      throw err;
    }
  }

  // Fallback: trigger browser download (respects name as-is).
  const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = name;
  anchor.style.display = 'none';
  document.body.appendChild(anchor);
  anchor.click();
  document.body.removeChild(anchor);
  URL.revokeObjectURL(url);
  return { filename: name };
}

/** Read files passed via Launch Queue (file_handlers). */
export async function readLaunchFiles(
  launchParams: LaunchParams
): Promise<OpenFileResult[]> {
  const results: OpenFileResult[] = [];

  for (const handle of launchParams.files) {
    if (handle.kind !== 'file') continue;
    const fileHandle = handle as FileSystemFileHandle;
    const file = await fileHandle.getFile();
    const content = await readFileAsText(file);
    results.push({
      filename: file.name,
      content,
      fileHandle,
    });
  }

  return results;
}

/** Register Launch Queue handler for file_handlers manifest entries. */
export function registerLaunchHandler(
  onFiles: (files: OpenFileResult[]) => void
): void {
  if (!('launchQueue' in window)) return;

  window.launchQueue.setConsumer(async (params) => {
    const files = await readLaunchFiles(params);
    if (files.length) onFiles(files);
  });
}
